patch:
diff --git a/repro/no-useless-assignment-try-catch.js b/repro/no-useless-assignment-try-catch.js
new file mode 100644
index 0000000..06295b3
--- /dev/null
+++ b/repro/no-useless-assignment-try-catch.js
@@ -0,0 +1,53 @@
+"use strict";
+
+const rule = require("../lib/rules/no-useless-assignment");
+const RuleTester = require("../lib/rule-tester/rule-tester");
+
+const ruleTester = new RuleTester({ languageOptions: { ecmaVersion: "latest", sourceType: "module" } });
+
+ruleTester.run("no-useless-assignment (eslint#19245)", rule, {
+    valid: [
+
+        // Reporter's exact snippet: value assigned in try is read in catch.
+        `async function fn() {
+            let intermediaryValue;
+            try {
+                intermediaryValue = 42;
+                unsafeFn();
+                return { error: undefined };
+            } catch {
+                return { intermediaryValue };
+            }
+        }
+
+        function unsafeFn() {
+            throw new Error();
+        }`,
+
+        // Same with `break` in the try block instead of `return`.
+        `function fn() {
+            let v;
+            while (cond) {
+                try {
+                    v = 42;
+                    unsafeFn();
+                    break;
+                } catch {
+                    use(v);
+                }
+            }
+        }`,
+
+        // Control: without the return, the rule already accepts it.
+        `function fn() {
+            let intermediaryValue;
+            try {
+                intermediaryValue = 42;
+                unsafeFn();
+            } catch {
+                return { intermediaryValue };
+            }
+        }`
+    ],
+    invalid: []
+});
